d.korea={asOf:'2026.09.04',indices:[{label:'KOSPI',value:'6,687.21',sub:'▲ 107.73 · +1.64% · 외국인·기관 동반 순매수'},{label:'KOSDAQ',value:'813.50',sub:'▲ 23.29 · +2.95% · 800선 회복'}],narrative:'미국 국채금리와 달러 하락, 원화 강세가 국내 위험선호 회복의 출발점이 됐다. 외국인과 기관이 양 시장에서 함께 순매수했고 삼성전자·SK하이닉스에서 로봇·반도체 장비·핀테크로 상승 폭이 넓어졌다. 전일 기타법인 방어에 의존했던 반등보다 수급의 질은 개선됐지만 WTI 91달러대와 오늘 밤 미국 고용보고서라는 변동성 요인은 남아 있다.',flows:[{actor:'외국인',focus:'KOSPI +4,793억원 / KOSDAQ +2,600억원',reading:'양 시장 동반 순매수로 전환'},{actor:'기관',focus:'KOSPI +1조6,691억원 / KOSDAQ +1,601억원',reading:'대형주와 성장주 동시 매수'},{actor:'개인',focus:'KOSPI -3조7,224억원 / KOSDAQ -4,119억원',reading:'반등 구간에서 현물 차익실현'},{actor:'ETF 개인(전일)',focus:'레버리지 대규모 매도·인버스 순매수',reading:'9/3 방어적 포지션이 9/4 반등과 역행'}],sectors:[{name:'로봇',state:'최강',detail:'원익홀딩스 +29.9%, 로보티즈 +22.5%, KNR시스템 +16.1%'},{name:'반도체·소부장',state:'강세 확산',detail:'SK하이닉스 +3.2%, 한미반도체 +9.3%, 인텍플러스 +16.7%'},{name:'가상자산·STO·핀테크',state:'테마 강세',detail:'쿠콘 +14.2%, 헥토파이낸셜 +13.5%, 갤럭시아머니트리 +10.9%'},{name:'정유·에너지',state:'상대강세',detail:'S-Oil +6.4%, SK이노베이션 +5.7% · WTI 91달러대'},{name:'대형 반도체',state:'지수 견인',detail:'삼성전자 +2.2%, SK하이닉스 +3.2%'}]};

d.daily.push({date:'2026-09-04',month:'2026년 9월',title:'금리·달러 완화가 외국인·기관 복귀를 이끌고 로봇·반도체로 위험선호가 확산된 날',tags:['외국인복귀','기관순매수','로봇','반도체','WTI91'],lead:['9월 4일 코스피는 6,687.21로 1.64%, 코스닥은 813.50으로 2.95% 상승했다. 외국인과 기관이 양 시장에서 동반 순매수했고 원·달러가 1,350.40원으로 하락하면서 전일의 수급 공백이 위험선호 회복으로 전환됐다.','전일 밤 미국에서는 ISM 서비스업이 55.4로 예상보다 강했지만 단위노동비용은 1.2%로 예상을 밑돌았다. 경기 급락 없이 비용 압력이 완화될 수 있다는 조합에 미국 2년물·10년물과 달러가 하락하고 주식시장은 광범위하게 상승했다. 이 금융여건 완화가 국내 반도체 대형주에서 로봇·소부장·핀테크로 확산됐지만 WTI 91달러대는 여전히 핵심 반대축이다.'],report:[
 {no:'02',title:'전일 미국시장: 견조한 서비스와 완화된 노동비용',paragraphs:['미국 ISM 서비스업은 55.4로 시장 예상 54.1 안팎을 웃돌았고 신규 실업수당 청구는 20.6만건으로 예상에 대체로 부합했다. 서비스 경기는 확장세를 유지하고 고용이 급격히 무너지는 신호는 제한적이었다.','비농업 생산성은 1.4%, 단위노동비용은 1.2%로 집계돼 노동비용은 예상 1.3%를 소폭 밑돌았다. 강한 서비스 수요와 완화된 비용 압력의 조합은 스태그플레이션 우려를 낮추며 미국 주식의 상승 폭을 산업재·금융·경기민감주까지 넓혔다.','미국 2년물은 4.340%, 10년물은 4.768%, DXY는 98.995로 하락했고 S&P500 +1.06%, 다우 +1.18%, 나스닥100 +1.16%로 마감했다. Waller의 조건부 동결 발언은 물가가 다시 가속하면 인상할 수 있다는 단서를 남겨 완화 전환으로 단정할 단계는 아니다.']},
 {no:'03',title:'국내 지수와 수급: 외국인·기관의 동시 복귀',paragraphs:['코스피는 107.73포인트 오른 6,687.21(+1.64%), 코스닥은 23.29포인트 오른 813.50(+2.95%)로 마감했다. 코스닥이 800선을 하루 만에 회복하고 상승률이 코스피를 웃돈 것은 위험선호가 대형주 방어를 넘어 성장주로 확산됐음을 뜻한다.','코스피에서 외국인은 4,793억원, 기관은 1조6,691억원 순매수했고 개인은 3조7,224억원 순매도했다. 코스닥도 외국인 2,600억원, 기관 1,601억원 순매수, 개인 4,119억원 순매도였다. 전일 기타법인 매수에 의존했던 지수 방어와 달리 오늘은 전통적인 위험선호 주체가 양 시장에 복귀했다.','원·달러는 전일보다 8.90원 내린 1,350.40원에 마감했다. 미국 달러 약세와 원화 강세가 외국인의 환차손 우려를 낮추고 삼성전자·SK하이닉스 및 코스닥 성장주 매수의 배경이 됐다.']},
 {no:'04',title:'주도 업종: 로봇·반도체·핀테크로 Breadth 확대',paragraphs:['로봇에서는 원익홀딩스 +29.9%, 로보티즈 +22.5%, KNR시스템 +16.1%, SPG +12.4%가 상승했다. 외국인·기관 잠정 동반매수 후보에 로보티즈와 SK하이닉스가 함께 포착돼 테마성 급등과 핵심 수급의 연결 여부를 추적할 가치가 생겼다.','반도체는 삼성전자 +2.2%, SK하이닉스 +3.2%가 지수를 견인했고 한미반도체 +9.3%, 인텍플러스 +16.7%, PSK홀딩스 +11.2%, 테스 +9.6%, 원익IPS +9.3%로 장비·소재까지 확산됐다. AI 수요와 HBM 투자 기대가 달러·금리 완화라는 할인율 호재를 만난 결과다.','가상자산·STO·핀테크는 쿠콘 +14.2%, 헥토파이낸셜 +13.5%, 갤럭시아머니트리 +10.9%로 강했다. 글로벌 대형은행의 공동 달러 스테이블코인 추진 보도가 촉매가 됐지만 참여사·사업구조가 공식 확정되기 전까지는 국내 기업의 실제 매출 연결보다 정책·테마 민감도로 분류한다.']},
 {no:'05',title:'개인 ETF 포지션이 보여준 반등의 역설',paragraphs:['9월 3일 기준 개인은 KODEX 레버리지 1,025억원, 코스닥150레버리지 942억원, KODEX200 472억원, SK하이닉스 단일종목 레버리지 416억원을 순매도했다. 반대로 SK하이닉스 인버스2X 144억원, 코스피200선물인버스2X 142억원, 코스닥150선물인버스 130억원을 순매수했다.','전일 장중 변동성이 커진 뒤 개인이 공격적 반등 베팅을 줄이고 하방 헤지를 늘린 바로 다음 날 외국인·기관 주도의 강한 반등이 나왔다. 이는 단기 포지션이 위험회피 쪽으로 기울어 있었음을 보여주며, 상승 지속 시 인버스 청산이 추가 탄력을 만들 수 있다.','반대로 오늘 현물 개인 순매도 규모가 매우 컸던 만큼 외국인·기관 매수가 하루에 그치면 추격 수요가 약해질 수 있다. ETF 수급은 방향 예측보다 포지션 쏠림과 잠재적 되감기 압력을 보는 보조지표로 사용한다.']},
 {no:'06',title:'WTI 91달러와 공급측 물가: 반등의 제약조건',paragraphs:['WTI는 91.67달러로 90달러 위에 머물렀다. 러시아 정유시설 차질과 호르무즈 위험, 낮은 정제품 재고가 디젤 가격을 끌어올리며 원유보다 실물경제에 직접적인 비용 충격을 만들고 있다.','국내에서는 S-Oil +6.4%, SK이노베이션 +5.7%로 정유·에너지가 상승했다. 제품 스프레드 확대는 정유사와 일부 탱커에 기회지만 항공·육상운송·건설·소비재에는 마진 압박이다. 한국산 디젤의 이례적인 유럽향 수출은 지역 간 가격차가 장거리 운임을 감당할 만큼 벌어졌다는 정황이다.','따라서 오늘의 금리·달러 하락을 추세적 완화로 바로 연장하지 않는다. 유가·디젤 → 운송·생산비 → 기대인플레이션 → 장기금리의 경로가 재가동되는지 확인해야 한다.']},
 {no:'07',title:'산업 판단과 운용 결론',paragraphs:['AI 투자는 HBM과 반도체 장비, 데이터센터 전력·냉각·로봇 자동화로 수혜 범위를 넓히고 있다. 다만 공급망 기업은 현재 매출을 인식하는 반면 투자 주체의 비용은 감가상각을 통해 늦게 반영되므로 AI 최종사용자의 지불의사와 투자수익률은 별도로 검증한다.','일본의 장기금리 상승과 엔화 경로는 글로벌 캐리 트레이드의 또 다른 변수다. 성장·생산성 개선을 동반한 금리 상승과 통화 신뢰 훼손형 금리 상승은 주식에 미치는 영향이 반대이므로 JGB·엔화·은행주를 함께 본다.','운용상 오늘 반등은 외국인·기관 동반매수, 원화 강세, 코스닥의 상대강세와 업종 확산을 동반해 전일보다 질이 좋았다. 반도체·로봇·전력 인프라의 실적 가시성이 있는 종목을 우선하되 WTI와 장기금리가 다시 오르거나 외국인 수급이 역전되면 위험노출을 빠르게 조절한다.']}
 ],watch:['오늘 밤 발표되는 미국 NFP·실업률·임금은 9월 4일 보고서에 섞지 않고 9월 7일 국내 시황의 선행변수로 반영한다.','외국인·기관의 양 시장 동반 순매수가 다음 거래일에도 이어지는지 확인한다.','원·달러 1,350원과 미국 10년물 4.77% 부근의 안정 여부를 본다.','WTI 90달러 안착, 디젤 크랙스프레드와 호르무즈 통항 상황을 추적한다.','로봇·반도체 장비 강세가 거래대금·수주·이익추정치 상향을 동반하는지 확인한다.','스테이블코인 공동 프로젝트의 공식 참여사와 국내 핀테크의 실제 수익모델을 검증한다.']});

